mapper.select:
SELECT

FROM equipment_sensor_monitor m
INNER JOIN equipment_sensor s ON m.sensor_id = s.id


        AND m.sensor_id = #{query.sensorId}


        AND s.equipment_id = #{query.equipmentId}


        AND m.create_time >= #{query.startTime}


        AND m.create_time <= #{query.endTime}

    AND m.delete_flag = 0
    AND s.delete_flag = 0

ORDER BY m.create_time DESC
